using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;using VirgilPatch;
class StartupRepairTests {
 const string Key="!Chronicles-TexturePatch(3.2.0)";static string root;static int passed;static JavaScriptSerializer js=new JavaScriptSerializer();
 static void Assert(bool b,string why){if(!b)throw new Exception(why);}static void Reject(Action a){try{a();}catch(Exception){return;}throw new Exception("Expected rejection");}static void Test(string n,Action a){a();passed++;Console.WriteLine("PASS "+n);}
 static State Fresh(){string area=Path.Combine(root,Guid.NewGuid().ToString("N"));Config.StateDir=Path.Combine(area,"state");var s=new State{patches_dir=Path.Combine(area,"Patches")};s.install_folders[Key]=FolderMigration.Canonical(Key);string dir=Dir(s);Directory.CreateDirectory(dir);var rows=new List<object>();uint id=107009;foreach(string name in new[]{"Wallpiece05.wmo","Wallpiece05_000.wmo"}){byte[] bytes=Encoding.UTF8.GetBytes(name+" content");File.WriteAllBytes(Path.Combine(dir,name.ToLowerInvariant()),bytes);rows.Add(new{file=name,id=id++});s.installed[Key+"/"+name]=RepairSource.Sha(bytes);}File.WriteAllText(Path.Combine(dir,"patch.json"),js.Serialize(new{name=Key,files=rows}));return s;}
 static string Dir(State s){return Path.Combine(s.patches_dir,FolderMigration.Canonical(Key));}static bool Exact(State s,string n){return Directory.EnumerateFiles(Dir(s)).Any(p=>Path.GetFileName(p)==n);}static int Repair(State s){return StartupCasingRepair.Apply(s,Console.WriteLine);}
 [STAThread]static int Main(string[] a){try{root=Path.GetFullPath(a[0]);Directory.CreateDirectory(root);Config.StartAmbienceMuted=true;
 Test("startup-repairs-known-files-without-changing-bytes-or-metadata",delegate{var s=Fresh();string meta=File.ReadAllText(Path.Combine(Dir(s),"patch.json"));Assert(Repair(s)==2&&Exact(s,"Wallpiece05.wmo")&&Exact(s,"Wallpiece05_000.wmo"),"Known files not repaired");Assert(File.ReadAllText(Path.Combine(Dir(s),"patch.json"))==meta,"Metadata changed");foreach(string n in new[]{"Wallpiece05.wmo","Wallpiece05_000.wmo"})Assert(Updater.BlobSha(Path.Combine(Dir(s),n))==s.installed[Key+"/"+n],"Asset bytes changed");Assert(Repair(s)==0,"Repair repeats");});
 Test("both-checksums-must-match-before-either-rename",delegate{var s=Fresh();File.WriteAllText(Path.Combine(Dir(s),"wallpiece05_000.wmo"),"modified development file");Assert(Repair(s)==0&&Exact(s,"wallpiece05.wmo"),"Partial or modified install renamed");});
 Test("missing-files-remain-for-manual-update",delegate{var s=Fresh();File.Delete(Path.Combine(Dir(s),"wallpiece05_000.wmo"));Assert(Repair(s)==0&&Exact(s,"wallpiece05.wmo"),"Missing companion caused partial repair");});
 Test("unknown-checksum-or-unmapped-install-is-preserved",delegate{var s=Fresh();s.installed.Clear();Assert(Repair(s)==0&&Exact(s,"wallpiece05.wmo"),"Unknown hashes trusted");s=Fresh();s.install_folders.Clear();Assert(Repair(s)==0&&Exact(s,"wallpiece05.wmo"),"Unmapped patch changed");});
 Test("incorrect-ids-and-duplicate-json-are-rejected",delegate{var s=Fresh();string p=Path.Combine(Dir(s),"patch.json");File.WriteAllText(p,File.ReadAllText(p).Replace("107009","107011"));Reject(()=>Repair(s));Assert(Exact(s,"wallpiece05.wmo"),"Incorrect ID renamed");s=Fresh();p=Path.Combine(Dir(s),"patch.json");File.WriteAllText(p,"{\"files\":[],"+File.ReadAllText(p).Substring(1));Reject(()=>Repair(s));Assert(Exact(s,"wallpiece05.wmo"),"Duplicate JSON renamed");});
 Test("concurrent-updater-lock-prevents-startup-rename",delegate{var s=Fresh();using(Updater.AcquirePatchLock(s.patches_dir)){Reject(()=>Repair(s));Assert(Exact(s,"wallpiece05.wmo"),"Concurrent repair changed files");}Assert(Repair(s)==2,"Retry failed");});
 Test("other-patches-and-development-files-are-preserved",delegate{var s=Fresh();string other=Path.Combine(s.patches_dir,"Other");Directory.CreateDirectory(other);File.WriteAllText(Path.Combine(other,"wallpiece05.wmo"),"keep");File.WriteAllText(Path.Combine(Dir(s),"Extra.BLP"),"keep");Assert(Repair(s)==2,"Known repair failed");Assert(File.Exists(Path.Combine(other,"wallpiece05.wmo"))&&File.Exists(Path.Combine(Dir(s),"Extra.BLP")),"Unrelated file changed");});
 Test("actual-window-launch-repairs-without-update-click",delegate{var s=Fresh();s.Save();string empty=Path.Combine(root,"empty-source");Directory.CreateDirectory(empty);using(var form=new MainForm(new FolderSource(empty),null,true)){form.Opacity=0;form.Show();Application.DoEvents();Assert(Exact(s,"Wallpiece05.wmo")&&Exact(s,"Wallpiece05_000.wmo"),"Launch did not repair");form.Close();}});
 Console.WriteLine("TOTAL "+passed+" automatic startup cases passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
